import React, { useState, useRef, DragEvent } from 'react';
import ColorThief from 'color-thief-browser';

interface ColorGuideProps {
  onBack: () => void;
  onHome: () => void;
  onNextStep: (color: string) => void;
}

const PALETTE_COUNT = 8;

function colorDistance(a: [number, number, number], b: [number, number, number]) {
  return Math.sqrt(
    Math.pow(a[0] - b[0], 2) +
    Math.pow(a[1] - b[1], 2) +
    Math.pow(a[2] - b[2], 2)
  );
}

function filterSimilarColors(palette: [number, number, number][], threshold = 40) {
  const result: [number, number, number][] = [];
  palette.forEach(color => {
    if (!result.some(existing => colorDistance(existing, color) < threshold)) {
      result.push(color);
    }
  });
  return result;
}

const ColorGuide: React.FC<ColorGuideProps> = ({ onBack, onHome, onNextStep }) => {
  const [selectedColor, setSelectedColor] = useState('#f9f6f1');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [extractedColors, setExtractedColors] = useState<string[]>([]);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragActive, setDragActive] = useState(false);

  // 이미지 업로드 처리 (input)
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        setUploadedImage(imageUrl);
      };
      reader.readAsDataURL(file);
    }
  };

  // 드래그 앤 드롭 업로드
  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragActive(false);
    if (event.dataTransfer.files && event.dataTransfer.files[0]) {
      const file = event.dataTransfer.files[0];
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        setUploadedImage(imageUrl);
      };
      reader.readAsDataURL(file);
    }
  };
  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragActive(true);
  };
  const handleDragLeave = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragActive(false);
  };

  // 이미지 onLoad에서 팔레트 추출
  const handleImageLoaded = async (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    const img = e.currentTarget;
    try {
      let palette = await ColorThief.getPalette(img, PALETTE_COUNT * 2);
      palette = filterSimilarColors(palette, 40).slice(0, PALETTE_COUNT);
      const hexPalette = palette.map(([r, g, b]: [number, number, number]) =>
        '#' + [r, g, b].map(x => x.toString(16).padStart(2, '0')).join('')
      );
      setExtractedColors(hexPalette);
      if (hexPalette.length > 0) setSelectedColor(hexPalette[0]);
    } catch (e) {
      setExtractedColors([]);
    }
  };

  // 캔버스 클릭으로 색상 선택
  const handleCanvasClick = (event: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const ctx = canvas.getContext('2d');
    const pixel = ctx?.getImageData(x, y, 1, 1).data;
    if (pixel) {
      const color = `#${pixel[0].toString(16).padStart(2, '0')}${pixel[1].toString(16).padStart(2, '0')}${pixel[2].toString(16).padStart(2, '0')}`;
      setSelectedColor(color);
    }
  };

  // 이미지 미리보기 및 캔버스 그리기
  React.useEffect(() => {
    if (uploadedImage && canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = new window.Image();
      img.onload = () => {
        const maxSize = 300;
        let { width, height } = img;
        if (width > height) {
          if (width > maxSize) {
            height = (height * maxSize) / width;
            width = maxSize;
          }
        } else {
          if (height > maxSize) {
            width = (width * maxSize) / height;
            height = maxSize;
          }
        }
        canvas.width = width;
        canvas.height = height;
        ctx?.drawImage(img, 0, 0, width, height);
      };
      img.src = uploadedImage;
    }
  }, [uploadedImage]);

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 뒤로가기
          </button>
          <button className="btn-home" onClick={onHome}>
            🏠 홈
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            🎨 배경 컬러 추천받기
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            📸 이미지에서 컬러 추출하기
          </h3>
          <div
            className="card"
            style={{ textAlign: 'center', padding: '30px', border: dragActive ? '2px dashed #3b82f6' : undefined, background: dragActive ? '#f0f6ff' : undefined }}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
          >
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              onChange={handleImageUpload}
              style={{ display: 'none' }}
            />
            {!uploadedImage ? (
              <div>
                <div style={{ fontSize: '3rem', marginBottom: '20px' }}>📁</div>
                <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>이미지 업로드</h4>
                <p style={{ color: '#64748b', marginBottom: '20px' }}>
                  이미지를 클릭하거나, 이 영역에 드래그해서 업로드할 수 있어요
                </p>
                <button 
                  className="btn" 
                  onClick={() => fileInputRef.current?.click()}
                  style={{ 
                    fontSize: '1.1rem', 
                    padding: '12px 24px',
                    background: '#3b82f6',
                    color: 'white'
                  }}
                >
                  이미지 선택하기
                </button>
              </div>
            ) : (
              <div>
                <img
                  src={uploadedImage}
                  alt="업로드 이미지"
                  style={{
                    maxWidth: 220,
                    maxHeight: 220,
                    borderRadius: '16px',
                    marginBottom: '12px',
                    boxShadow: '0 2px 12px #e5e7eb',
                    objectFit: 'cover',
                    display: 'block',
                    marginLeft: 'auto',
                    marginRight: 'auto'
                  }}
                  crossOrigin="anonymous"
                  onLoad={handleImageLoaded}
                />
                <div style={{ marginBottom: '20px' }}>
                  <canvas
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    style={{
                      border: '2px solid #e5e7eb',
                      borderRadius: '12px',
                      cursor: 'crosshair',
                      maxWidth: '100%',
                      height: 'auto',
                      marginTop: '10px'
                    }}
                  />
                  <p style={{ color: '#64748b', fontSize: '0.9rem', marginTop: '10px' }}>
                    이미지를 클릭하여 원하는 색상을 선택하세요
                  </p>
                </div>
                {extractedColors.length > 0 && (
                  <div style={{ marginBottom: '16px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '8px', justifyContent: 'center', alignItems: 'center' }}>
                      {extractedColors.map((color, index) => (
                        <div
                          key={index}
                          style={{
                            width: '36px',
                            height: '36px',
                            background: color,
                            borderRadius: '8px',
                            border: selectedColor === color ? '3px solid #3b82f6' : '2px solid #e5e7eb',
                            cursor: 'pointer',
                            transition: 'all 0.2s ease',
                            boxSizing: 'border-box'
                          }}
                          onClick={() => setSelectedColor(color)}
                          title={color}
                        />
                      ))}
                    </div>
                    <div style={{ marginTop: '10px', textAlign: 'center' }}>
                      <span style={{ fontWeight: 700, color: '#334155', fontSize: '1rem' }}>선택된 색상</span><br/>
                      <span style={{
                        display: 'inline-block',
                        width: '32px',
                        height: '32px',
                        background: selectedColor,
                        borderRadius: '7px',
                        border: '2px solid #e5e7eb',
                        margin: '6px 0 2px 0',
                        verticalAlign: 'middle'
                      }} />
                      <div style={{ color: '#64748b', fontWeight: 'bold', fontSize: '0.95rem' }}>{selectedColor}</div>
                    </div>
                  </div>
                )}
                <button 
                  className="btn" 
                  onClick={() => {
                    setUploadedImage(null);
                    setExtractedColors([]);
                  }}
                  style={{ marginRight: '10px' }}
                >
                  다른 이미지 선택
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            🎨 커스텀 컬러 선택
          </h3>
          <div className="card" style={{ textAlign: 'center', padding: '30px' }}>
            <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>직접 컬러 선택하기</h4>
            <input 
              type="color" 
              value={selectedColor}
              onChange={(e) => setSelectedColor(e.target.value)}
              style={{ 
                width: '100px', 
                height: '60px', 
                border: 'none', 
                borderRadius: '12px',
                cursor: 'pointer'
              }}
            />
            <div style={{ 
              marginTop: '15px', 
              padding: '10px', 
              background: selectedColor, 
              borderRadius: '8px',
              color: selectedColor === '#ffffff' ? '#000' : '#fff',
              fontWeight: 'bold'
            }}>
              선택된 컬러: {selectedColor}
            </div>
          </div>
        </div>

        <div className="mb-20" style={{ textAlign: 'center' }}>
          <button 
            className="btn" 
            style={{ 
              fontSize: '1.2rem', 
              padding: '15px 30px',
              background: '#3b82f6',
              color: 'white',
              border: 'none',
              borderRadius: '12px',
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
            onClick={() => onNextStep(selectedColor)}
          >
            다음 단계: 텍스트 컬러 선택하기 →
          </button>
        </div>

        <div className="warning">
          <strong>💡 팁:</strong><br/>
          • 이미지를 업로드하면 자동으로 주요 색상들이 추출됩니다<br/>
          • 추출된 팔레트에서 원하는 색상을 클릭하거나, 이미지를 직접 클릭해서 정확한 색상을 선택하세요<br/>
          • 색상 선택 후 다음 단계로 넘어가면 텍스트 컬러를 추천받을 수 있습니다
        </div>
      </div>
    </div>
  );
};

export default ColorGuide;
